// Runs before `next build` (see package.json "build").
// public/sw.js is generated by scripts/build-offline.mjs AFTER next build and is not committed, so
// on a clean checkout (new clone, CI, deployment) it does not exist when Next.js traces the
// /offline-worker route, and the worker would be left out of the deployment. Create a placeholder
// so the trace includes the file; build-offline.mjs overwrites it with the real worker and fails
// the build if the route trace or the worker is missing. An existing worker is left as it is.
import { access, mkdir, writeFile } from 'node:fs/promises'

const file = 'public/sw.js'
try {
  await access(file)
} catch {
  await mkdir('public', { recursive: true })
  await writeFile(file, '// Placeholder: replaced by scripts/build-offline.mjs during `pnpm build`.\n')
  console.log('Offline worker placeholder created for the build trace.')
}
